extension xinstall {
  /*
   * parseid --
   *  parse uid or gid from arg into id, returning non-zero if successful
   */
  func parseid(_ name : String) -> UInt? {
    return UInt(name)
  }

  /*
   * quiet_mktemp --
   *  mktemp implementation used mkstemp to avoid mktemp warnings.  We
   *  really do need mktemp semantics here as we will be creating a link.
   */
  func quiet_mktemp(_ template : String) -> String? {
    guard var k = strdup(template) else {
      fatalError("not enough memory to create filename")
    }
    defer { free(k) }
    let fd = mkstemp(&k)
    if fd < 0 {
      return nil
    }
    close(fd)
    if unlink(k) == -1 {
      err(Int(EX_OSERR), "unlink \(k)")
    }
    return String(cString: k)
  }

  /*
   * do_link --
   *  make a hard link, obeying dorename if set
   *  return -1 on failure
   */
  func do_link(_ from_name : FilePath, _ to_name : FilePath, _ target_sb : FileMetadata?) -> Int {
    var ret = 0
    if let target_sb {
      var tmpl = "\(to_name.string).inst.XXXXXX"
      /* This usage is safe. */
      guard let tmpl = quiet_mktemp(tmpl) else {
        err( Int(EX_OSERR), "\(tmpl): mktemp")
      }
      ret = Int(link(from_name.string, tmpl))
      if ret == 0 {
        if target_sb.filetype == .directory && rmdir(to_name.string) == -1 {
          unlink(tmpl)
          err(Int(EX_OSERR), to_name.string)
        }

        if target_sb.flags.containsAny(of: NOCHANGEBITS) {
          chflags(to_name.string, target_sb.flags.subtracting(NOCHANGEBITS).rawValue)
        }

        if 0 != options.verbose {
          print("install: link \(from_name.string) -> \(to_name.string)")
        }
        ret = Int(rename(tmpl, to_name.string))
        /*
         * If rename has posix semantics, then the temporary
         * file may still exist when from_name and to_name point
         * to the same file, so unlink it unconditionally.
         */
        unlink(tmpl)
      }
      return ret
    } else {
      if 0 != options.verbose {
        print("install: link \(from_name) -> \(to_name)")
      }
      return Int(link(from_name.string, to_name.string))
    }
  }

  /*
   * do_symlink --
   *  Make a symbolic link, obeying dorename if set. Exit on failure.
   */
  func do_symlink(_ from_name : FilePath, _ to_name : FilePath, _ target_sb : FileMetadata?) {
    if let target_sb {
      var tmpl = "\(to_name.string).inst.XXXXXX"
      /* This usage is safe. */
      guard let tmpl = quiet_mktemp(tmpl) else  {
        err(Int(EX_OSERR), "\(tmpl): mktemp")
      }

      if symlink(from_name.string, tmpl) == -1 {
        err(Int(EX_OSERR), "symlink \(from_name.string) -> \(tmpl)")
      }

      if target_sb.filetype == .directory && rmdir(to_name.string) == -1 {
        unlink(tmpl)
        err(Int(EX_OSERR), to_name.string)
      }

      if target_sb.flags.containsAny(of: NOCHANGEBITS) {
        chflags(to_name.string, target_sb.flags.subtracting(NOCHANGEBITS).rawValue)
      }

      if 0 != options.verbose {
        print("install: symlink \(from_name.string) -> \(to_name.string)")
      }
      if rename(tmpl, to_name.string) == -1 {
        /* Remove temporary link before exiting. */
        unlink(tmpl)
        err(Int(EX_OSERR), "\(to_name.string): rename")
      }
    } else {
      if options.verbose != 0 {
        print("install: symlink \(from_name.string) -> \(to_name.string)")
      }
      if symlink(from_name.string, to_name.string) == -1 {
        err(Int(EX_OSERR), "symlink \(from_name.string) -> \(to_name.string)")
      }
    }
  }

  /*
   * makelink --
   *  make a link from source to destination
   */
  func makelink(_ from_name : FilePath, _ to_name : FilePath, _ target_sb : FileMetadata?) {
//    char src[MAXPATHLEN], dst[MAXPATHLEN], lnk[MAXPATHLEN];
//    char *to_name_copy, *d, *ld, *ls, *s;
//    const char *base, *dir;

    /* Try hard links first. */
    if options.dolink.containsAny(of: [.HARD, .MIXED ] ) {
      if (do_link(from_name, to_name, target_sb) == -1) {
        if options.dolink.contains(.HARD) || errno != EXDEV {
          err(Int(EX_OSERR), "link \(from_name) -> \(to_name)")
        }
      } else {
        guard let to_sb = try? FileMetadata(for: to_name) else {
          err(Int(EX_OSERR), "\(to_name): stat")
        }

        if to_sb.filetype == .regular {
          /*
           * XXX: hard links to anything other than
           * plain files are not metalogged
           */
//          int omode;
//          const char *oowner, *ogroup;
//          char *offlags;
//          char *dres;

          /*
           * XXX: use underlying perms, unless
           * overridden on command line.
           */
          let omode = options.mode
          if !options.haveopt_m {
            options.mode = to_sb.permissions.rawValue & 0o0777
          }
          let oowner = options.owner
          if !options.haveopt_o {
            options.owner = nil
          }
          let ogroup = group
          if !options.haveopt_g {
            options.group = nil
          }
          let offlags = options.fflags
          if !options.haveopt_f {
            options.fflags = nil
          }
          let dres = digest_file(from_name)

          metadata_log(to_name, "file", nil, nil, dres, Int64(to_sb.size))

          mode = omode;
          owner = oowner;
          group = ogroup;
          fflags = offlags;
        }
        return
      }
    }

    /* Symbolic links. */
    if options.dolink.contains(.ABSOLUTE) {
      /* Convert source path to absolute. */
      guard let _ = realpath(from_name.string, src) else {
        err(Int(EX_OSERR), "\(from_name.string): realpath")
      }
      do_symlink(src, to_name, target_sb);
      /* XXX: src may point outside of destdir */
      metadata_log(to_name, "link", nil, src, nil, 0)
      return
    }

    if options.dolink.contains(.RELATIVE) {
      if from_name.string.first != "/" {
        /* this is already a relative link */
        do_symlink(from_name, to_name, target_sb);
        /* XXX: from_name may point outside of destdir. */
        metadata_log(to_name, "link", nil, from_name, nil, 0)
        return
      }

      /* Resolve pathnames. */
      guard let _ = realpath(from_name, src) else {
        err(Int(EX_OSERR), "\(from_name): realpath")
      }

      /*
       * The last component of to_name may be a symlink,
       * so use realpath to resolve only the directory.
       */
      let to_name_copy = to_name
      let base = basename(to_name_copy.string)
      if base == to_name_copy.string {
        /* destination is a file in cwd */
        (void)strlcpy(dst, "./", sizeof(dst));
      } else if (base == to_name_copy + 1) {
        /* destination is a file in the root */
        (void)strlcpy(dst, "/", sizeof(dst));
      } else {
        /* all other cases: safe to call dirname() */
        dir = dirname(to_name_copy);
        if (realpath(dir, dst) == NULL) {
          err(EX_OSERR, "%s: realpath", dir);
        }
        if (strcmp(dst, "/") != 0 &&
            strlcat(dst, "/", sizeof(dst)) >= sizeof(dst)) {
          errx(1, "resolved pathname too long");
        }
      }
      if (strlcat(dst, base, sizeof(dst)) >= sizeof(dst)) {
        errx(1, "resolved pathname too long");
      }

      /* Trim common path components. */
      ls = ld = NULL;
      for (s = src, d = dst; *s == *d; ls = s, ld = d, s++, d++) {
        continue;
      }
      /*
       * If we didn't end after a directory separator, then we've
       * falsely matched the last component.  For example, if one
       * invoked install -lrs /lib/foo.so /libexec/ then the source
       * would terminate just after the separator while the
       * destination would terminate in the middle of 'libexec',
       * leading to a full directory getting falsely eaten.
       */
      if ((ls != NULL && *ls != '/') || (ld != NULL && *ld != '/')) {

        (void)s--, d--;
      }

      while (*s != '/') {
        (void)s--, d--;
      }

      /* Count the number of directories we need to backtrack. */
      for (++d, lnk[0] = '\0'; *d; d++) {
        if (*d == '/') {
          (void)strlcat(lnk, "../", sizeof(lnk));
        }
      }

      (void)strlcat(lnk, ++s, sizeof(lnk));

      do_symlink(lnk, to_name, target_sb);
      /* XXX: Link may point outside of destdir. */
      metadata_log(to_name, "link", NULL, lnk, NULL, 0);
      return;
    }

    /*
     * If absolute or relative was not specified, try the names the
     * user provided.
     */
    do_symlink(from_name, to_name, target_sb);
    /* XXX: from_name may point outside of destdir. */
    metadata_log(to_name, "link", nil, from_name, nil, 0);
  }

  /*
   * install --
   *  build a path name and install the file
   */
  func install(_ from_name : FilePath, _ to_namex : FilePath, _ fset : FileFlags, _ flags : IFlags) {
    //    struct stat from_sb, temp_sb, to_sb;
    //    struct timespec tsb[2];
    //    int devnull, files_match, from_fd, serrno, stripped, target;
    //    int temp_fd, to_fd;
    //    char backup[MAXPATHLEN], *p, pathbuf[MAXPATHLEN], tempfile[MAXPATHLEN];
    //    char *digestresult;

    //    digestresult = NULL;
//    files_match = stripped = 0;
    //    from_fd = -1;
    //    to_fd = -1;

    var devnull = false
    var to_name = to_namex
    var from_sb : FileMetadata

    /* If try to install NULL file to a directory, fails. */
    if flags.contains(.DIRECTORY) || from_name != FilePath(CMigration._PATH_DEVNULL) {
      if options.dolink.isEmpty {
        guard let fsb = try? FileMetadata(for: from_name) else {
          err(Int(EX_OSERR), from_name.string)
          fatalError()
        }
        from_sb = fsb
        if from_sb.filetype != .regular {
          errno = EFTYPE
          err(Int(EX_OSERR), from_name.string)
        }
      }
      /* Build the target path. */
      if flags.contains(.DIRECTORY) {
        to_name.append(from_name.components.last!)
      } else {
      }
      devnull = false
    } else {
      devnull = true
    }
    if to_name.isEmpty {
      errx(Int(EX_USAGE), "destination cannot be an empty string")
    }

    let to_sb = try? FileMetadata(for: to_name, followSymlinks: false)
    let target = to_sb != nil

    if options.dolink.rawValue != 0 {
      makelink(from_name, to_name, to_sb)
      return;
    }

    guard let to_sb else {
      err(Int(EX_CANTCREAT), to_name.string)
    }

    if to_sb.filetype == .regular, to_sb.filetype == .symbolicLink {
      errno = EFTYPE
      err(Int(EX_CANTCREAT), to_name.string)
    }


    guard devnull, let from_fd = try? FileDescriptor.open(from_name, .readOnly) else {
      //    if !devnull && (from_fd = open(from_name, O_RDONLY, 0)) < 0 {
      err(Int(EX_OSERR), from_name.string)
    }

    var files_match = false
    let to_fd : FileDescriptor

    /* If we don't strip, we can compare first. */
    if (options.docompare && !options.dostrip && target && to_sb.filetype == .regular) {
      guard let tfd = try? FileDescriptor.open(to_name,.readOnly) else {
        err(Int(EX_OSERR), to_name.string)
      }
      to_fd = tfd
      if devnull {
        files_match = to_sb.size == 0
      }
      else {
        files_match = !compare(from_fd, from_name, Int(from_sb.size),
                               to_fd,   to_name, Int(to_sb.size), &digestresult)
      }

      /* Close "to" file unless we match. */
      if !files_match {
        try? to_fd.close()
      }
    }

    if !files_match {
      var tempfile : FilePath
      (to_fd, tempfile) = create_tempfile(to_name)
      if (to_fd < 0) {
        /*
         * See rdar://138344946
         *
         * Xcode invokes us in a sandbox which only allows read access to the
         * source and write access to the destination, preventing us from
         * creating the temporary file.  We know this isn't a simple permission
         * issue on the destination directory because that would set errno to
         * EACCES instead of EPERM.  Fall back to copying directly to the
         * destination.
         */
        if (errno == EPERM) {
          warnx("sandbox detected, falling back to direct copy")
          if ((!target || unlink(to_name) == 0 || errno == ENOENT) &&
              (to_fd = open(to_name, O_RDWR|O_CREAT|O_EXCL, mode)) >= 0) {
            if (dostrip) {
              stripped = strip(to_name, to_fd, from_name,
                               &digestresult);
            }
            if (!stripped) {
              digestresult = copy(from_fd, from_name, to_fd,
                                  to_name, from_sb.st_size);
            }
            goto copied;
          }
          errno = EPERM;
          /* fall through to err() below */
        }

        err(Int(EX_OSERR), tempfile.string)

      }

      if !devnull {
        if options.dostrip {
          stripped = strip(tempfile.string, to_fd, from_name.string, &digestresult);
        }
        if (!stripped) {
          digestresult = copy(from_fd, from_name.string, to_fd, tempfile.string, Int64(from_sb.size))
        }
      }
    }

    if options.dostrip {
      if (!stripped) {
        strip(tempfile, to_fd, nil, &digestresult)
      }

      /*
       * Re-open our fd on the target, in case
       * we did not strip in-place.
       */
      try? to_fd.close()
      to_fd = try? FileDescriptor.open(tempfile, .readOnly)
      guard to_fd < 0 else {
        err(Int(EX_OSERR), "stripping \(to_name)")
      }
    }

    /*
     * Compare the stripped temp file with the target.
     */
    if (docompare && dostrip && target && S_ISREG(to_sb.st_mode)) {
      temp_fd = to_fd;

      /* Re-open to_fd using the real target name. */
      if ((to_fd = open(to_name, O_RDONLY, 0)) < 0) {
        err(EX_OSERR, "%s", to_name);
      }

      if (fstat(temp_fd, &temp_sb)) {
        serrno = errno;
        (void)unlink(tempfile);
        errno = serrno;
        err(EX_OSERR, "%s", tempfile);
      }

      if (compare(temp_fd, tempfile, (size_t)temp_sb.st_size, to_fd,
                  to_name, (size_t)to_sb.st_size, &digestresult)
          == 0) {
        /*
         * If target has more than one link we need to
         * replace it in order to snap the extra links.
         * Need to preserve target file times, though.
         */
        if (to_sb.st_nlink != 1) {
          tsb[0] = to_sb.st_atim;
          tsb[1] = to_sb.st_mtim;
          (void)utimensat(AT_FDCWD, tempfile, tsb, 0);
        } else {
          files_match = 1;
          (void)unlink(tempfile);
        }
        (void) close(temp_fd);
      }
    } else if options.dostrip {
      digestresult = digest_file(tempfile)
    }

    /*
     * Move the new file into place if the files are different (or
     * just not compared).
     */
    if !files_match {

      /* Try to turn off the immutable bits. */
      if to_sb.flags.containsAny(of: NOCHANGEBITS) {
        chflags(to_name, to_sb.flags.subtracting(NOCHANGEBITS).rawValue)
      }

      if target && options.dobackup {
        // FIXME: should I throw an error if filename too long?
        let backup = FilePath(to_name.string + options.suffix)
        if 0 != options.verbose {
          print("install: \(to_name.string) -> \(backup.string)")
        }
        if (unlink(backup.string) < 0 && errno != ENOENT) {
          let serrno = errno;

          if to_sb.flags.containsAny(of: NOCHANGEBITS) {
            chflags(to_name.string, to_sb.flags.rawValue)
          }

          unlink(tempfile.string)
          errno = serrno;
          err(Int(EX_OSERR), "unlink: \(backup)")
        }
        if (link(to_name.string, backup.string) < 0) {
          let serrno = errno;
          unlink(tempfile);

          if (to_sb.st_flags & NOCHANGEBITS) {
            Darwin.chflags(to_name.string, to_sb.flags.rawValue)
          }

          errno = serrno;
          err(Int(EX_OSERR), "link: \(to_name.string) to \(backup.string)")
        }
      }
      if 0 != options.verbose {
        print("install: \(from_name) -> \(to_name)")
      }
      if rename(tempfile, to_name) < 0 {
        let serrno = errno
        unlink(tempfile)
        errno = serrno
        err(Int(EX_OSERR), "rename: \(tempfile) to \(to_name.string)")
      }

      /* Re-open to_fd so we aren't hosed by the rename(2). */
      try? to_fd.close()
      if ((to_fd = open(to_name, O_RDONLY, 0)) < 0) {
        err(EX_OSERR, "%s", to_name);
      }
    }

  copied:
    /* in case mtime is modified */
    if (!devnull && (S_ISLNK(from_sb.st_mode) || S_ISREG(from_sb.st_mode)) &&
        fcopyfile(from_fd, to_fd, NULL, COPYFILE_XATTR) < 0) {
      warn("%s: unable to copy extended attributes from %s", to_name, from_name);
    }

    /*
     * Preserve the timestamp of the source file if necessary.
     */
    if (dopreserve && !files_match && !devnull) {
      tsb[0] = from_sb.st_atim;
      tsb[1] = from_sb.st_mtim;
      (void)utimensat(AT_FDCWD, to_name, tsb, 0);
    }

    guard let to_sb = try? FileMetadata(for: to_fd) else {
      let serrno = errno
      unlink(to_name.string)
      errno = serrno
      err(Int(EX_OSERR), to_name.string)
    }

    /*
     * Set owner, group, mode for target; do the chown first,
     * chown may lose the setuid bits.
     */
    if (!dounpriv && ((gid != (gid_t)-1 && gid != to_sb.st_gid) ||
                      (uid != (uid_t)-1 && uid != to_sb.st_uid) ||
                      (mode != (to_sb.st_mode & ALLPERMS)))) {

      /* Try to turn off the immutable bits. */
      if (to_sb.st_flags & NOCHANGEBITS) {
        (void)fchflags(to_fd, to_sb.st_flags & ~NOCHANGEBITS);
      }

    }

    if (!dounpriv && ((gid != (gid_t)-1 && gid != to_sb.st_gid) ||
                      (uid != (uid_t)-1 && uid != to_sb.st_uid))) {
      if (fchown(to_fd, uid, gid) == -1) {
        serrno = errno;
        (void)unlink(to_name);
        errno = serrno;
        err(EX_OSERR,"%s: chown/chgrp", to_name);
      }
    }
    if (mode != to_sb.permissions) {
      if (fchmod(to_fd.rawValue,
                 dounpriv ? mode & (S_IRWXU|S_IRWXG|S_IRWXO) : mode)) {
        let serrno = errno;
        unlink(to_name.string)
        errno = serrno;
        err(Int(EX_OSERR), "\(to_name.string): chmod")
      }
    }

    /*
     * If provided a set of flags, set them, otherwise, preserve the
     * flags, except for the dump flag.
     * NFS does not support flags.  Ignore ENOTSUP flags if we're just
     * trying to turn off UF_NODUMP.  If we're trying to set real flags,
     * then warn if the fs doesn't support it, otherwise fail.
     */
    if (!dounpriv && !devnull && (flags & SETFLAGS ||
                                  (from_sb.st_flags & ~UF_NODUMP) != to_sb.st_flags) &&
        fchflags(to_fd,
                 flags & SETFLAGS ? fset : from_sb.st_flags & ~UF_NODUMP)) {
      if (flags & SETFLAGS) {
        if (errno == ENOTSUP) {
          warn("\(to_name.string): chflags")
        }
        else {
          let serrno = errno;
          unlink(to_name.string)
          errno = serrno;
          err(Int(EX_OSERR), "\(to_name.string): chflags")
        }
      }
    }


    /* the ACL could prevent credential/permission system calls later on... */
    if (!devnull && (from_sb.filetype == .symbolicLink || from_sb.filetype == .regular) &&
        (fcopyfile(from_fd, to_fd, NULL, COPYFILE_ACL) < 0)) {
      warn("\(to_name.string): unable to copy ACL from \(from_name.string)")
    }

    try? to_fd.close()
    if (!devnull) {
      try? from_fd.close()
    }

    metadata_log(to_name, "file", tsb, nil, digestresult, to_sb.st_size);
    free(digestresult);
  }

